async function sha256(value) {
  return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value))), b => b.toString(16).padStart(2,'0')).join('');
}
async function db(path, method='GET', body, extra={}) {
  const headers = {'apikey':ADMIN_KEY,'Content-Type':'application/json',...extra};
  if (ADMIN_KEY.startsWith('eyJ')) headers.Authorization = 'Bearer ' + ADMIN_KEY;
  const res = await fetch(PROJECT_URL + '/rest/v1/' + path,{method,headers,body:body === undefined ? undefined : JSON.stringify(body),redirect:'error',signal:AbortSignal.timeout(7000)});
  if (!res.ok) { console.error('database_request_failed',res.status,path.split('?')[0]); throw new HttpError(503,'database_unavailable','Database belum dapat diakses. Coba lagi sebentar.'); }
  if (res.status === 204) return null;
  const text = await res.text();
  return text ? JSON.parse(text) : null;
}
const rpc = (name,body) => db('rpc/' + name,'POST',body);
async function limit(key,max,seconds) {
  return await rpc('hb_take_limit',{p_key:key,p_max:max,p_seconds:seconds});
}
async function providerFetch(url,headers,body,timeout,deadline) {
  const remaining = Math.min(timeout, deadline - Date.now());
  if (remaining < 1200) throw new HttpError(504,'provider_timeout','Batas waktu layanan AI tercapai.');
  const res = await fetch(url,{method:'POST',headers:{'Content-Type':'application/json',...headers},body:JSON.stringify(body),redirect:'error',signal:AbortSignal.timeout(remaining)});
  if (!res.ok) { console.warn('ai_provider_http_status',res.status); throw new HttpError(res.status,'provider_error','Penyedia AI belum tersedia.'); }
  return await res.json();
}
