 const food=coffee||breakfast||souvenir||has(/\b(makan|mak[ae]n|makanan|kuliner|kulineran|seafood|restoran|restaurants?|food|eat|gonggong|lendot|luti|bingka|mie|mi|noodles)\b/);
 const familyActivities=has(/main.*anak|bawa anak|bareng anak|\bkeluarga\b|\banak\b|\bfamily\b|\bkids\b|\bchildren\b/);
 const honeymoon=has(/honeymoon|bulan madu|romantis|romantic/);
 const trip=itineraryRequest(text,history);
 const itinerary=trip.enabled;
