 const weather=has(/cuaca|weather|forecast|suhu|temperature|hujan|rain/)&&!indoor&&!touring&&!hotel&&!food;
 const outside=has(/\b(bali|jakarta|surabaya|yogyakarta|jogja|bandung|lombok|medan|bintan|tanjung pinang)\b/);
 const focuses=[];if(has(/harga|tarif|tiket|biaya|budget|murah|price|cost|ticket|cheap|under|below|ribu|\brb\b/))focuses.push('price');
 if(has(/fasilitas|facilit|kolam|pool|wifi|parkir|parking|gym|spa|toilet/))focuses.push('facilities');
 if(has(/jam|buka|tutup|opening|hours|schedule|jadwal|check in|check out|checkin|checkout|check innya|check outnya/))focuses.push('hours');
 if(has(/alamat|lokasi|dimana|di mana|where|location|address/))focuses.push('location');
 let categories=null,category=null;
