 if(hotel){category='hotel';categories=['hotel'];}else if(food){category='kuliner';categories=['kuliner'];}else if(familyActivities){category='keluarga';categories=['keluarga'];}else if(indoor||noBeach){categories=TOUR_CATEGORIES;}else{const cats=activities.filter(([,re])=>re.test(q)).map(([c])=>c);if(cats.length){categories=cats.includes('pantai')?['pantai']:cats;category=categories.length===1?categories[0]:null;}else if(touring){categories=TOUR_CATEGORIES;}else if(has(/feri|ferry|batamfast|harbourfront|tanah merah|nongsapura/)){category='transportasi';categories=['transportasi'];}}
 const multi=honeymoon&&!hotel&&!food?['tourism','hotel']:itinerary&&food?['tourism','kuliner']:(hotel&&food&&has(/\b(dan|sama|serta|and|plus)\b/)?[...(touring?['tourism']:[]),'hotel','kuliner']:[]);
