async function readBody(req) {
  if (!req.headers.get('content-type')?.toLowerCase().startsWith('application/json')) throw new HttpError(415,'content_type','Gunakan JSON.');
  const reader = req.body?.getReader();
  if (!reader) throw new HttpError(400,'invalid_body','Permintaan kosong.');
  const chunks=[]; let size=0;
  while (true) {
    const {value,done}=await reader.read(); if(done) break;
    size+=value.byteLength;
    if(size>16000) { await reader.cancel(); throw new HttpError(413,'body_too_large','Permintaan terlalu panjang.'); }
    chunks.push(value);
  }
  const bytes=new Uint8Array(size); let offset=0;
  for(const chunk of chunks) {bytes.set(chunk,offset);offset+=chunk.byteLength;}
  let body;
  try {body=JSON.parse(new TextDecoder().decode(bytes));} catch {throw new HttpError(400,'invalid_json','JSON tidak valid.');}
  if (!body || typeof body !== 'object' || Array.isArray(body)) throw new HttpError(400,'invalid_json','JSON tidak valid.');
  return body;
}
